const searchCache=new WeakMap();function searchText(r){if(!searchCache.has(r))searchCache.set(r,[r.name,r.hanja,r.english,r.latin,r.plant,...(r.detail?.aliases||[]).map(a=>a.value)].join(' ').toLowerCase());return searchCache.get(r)}
const $=s=>document.querySelector(s);let records=[],saved=[],onlySaved=false,timer,current='sophorae-flos';const original=$('article').innerHTML;try{saved=JSON.parse(localStorage.getItem('bonchorok-bookmarks')||'[]');if(!Array.isArray(saved))saved=[]}catch{}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function notify(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2300)}
function render(){const q=$('#search').value.trim().toLowerCase();const filtered=records.filter(r=>(!onlySaved||saved.includes(r.id))&&searchText(r).includes(q));$('#results').replaceChildren();filtered.forEach(r=>{const b=document.createElement('button');b.className='herb-row'+(current===r.id?' selected':'');b.innerHTML=(r.id==='sophorae-flos'?'<img src="sophora.jpg" alt="">':'<span class="herb-initial"></span>')+'<span><strong></strong><small></small></span><span class="row-star"></span>';if(b.querySelector('.herb-initial'))b.querySelector('.herb-initial').textContent=r.name.slice(0,1);b.querySelector('strong').textContent=r.name+' '+r.hanja;b.querySelector('small').textContent=r.latin||r.plant;b.querySelector('.row-star').textContent=saved.includes(r.id)?'★':'›';b.onclick=()=>openHerb(r.id);$('#results').append(b)});if(!filtered.length){const p=document.createElement('p');p.className='list-empty';p.textContent=onlySaved?'저장한 약재가 없습니다.':'검색 결과가 없습니다.';$('#results').append(p)}$('#result-count').textContent=filtered.length+'종';const yes=saved.includes(current);$('#bookmark').textContent=yes?'★':'☆';$('#bookmark').setAttribute('aria-pressed',String(yes));$('#bookmark').setAttribute('aria-label',yes?'북마크 해제':'북마크 추가');$('#saved-count').textContent=saved.length;$('#all-filter').classList.toggle('active',!onlySaved);$('#bookmark-filter').classList.toggle('active',onlySaved)}
function setBookmark(value){saved=value?[...new Set([...saved,current])]:saved.filter(x=>x!==current);try{localStorage.setItem('bonchorok-bookmarks',JSON.stringify(saved));notify(value?'이 기기에 약재를 저장했습니다.':'북마크를 해제했습니다.')}catch{notify('브라우저 저장소를 사용할 수 없어 현재 화면에만 저장됩니다.')}render();return{herbId:current,saved:value}}
function gallery(type){document.querySelectorAll('[data-gallery]').forEach(b=>b.classList.toggle('active',b.dataset.gallery===type));$('#gallery-content').innerHTML=type==='plant'&&current==='sophorae-flos'?'<img class="gallery-photo" src="sophora.jpg" alt="회화나무의 크림색 꽃과 초록 잎" loading="lazy"><p class="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:Sophora_japonica_JPG2Fl.jpg" target="_blank" rel="noopener">Jean-Pol GRANDMONT / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a> · 일부 크롭</p>':'<div class="empty-block"><h3>확인된 이미지가 아직 없습니다</h3><p>출처와 품종이 확인된 자료를 등록한 뒤 제공됩니다.</p></div>'}
let observer;function bindArticle(){$('#bookmark').onclick=()=>setBookmark(!saved.includes(current));document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>gallery(b.dataset.gallery));gallery('plant');observer?.disconnect();observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('.toc>a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))})},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('.content-section').forEach(s=>observer.observe(s))}
function openHerb(id){const r=records.find(r=>r.id===id);if(!r)return;current=id;$('article').innerHTML=original;if(id!=='sophorae-flos'){$('.hero').classList.add('no-photo');$('.hero h1').innerHTML=esc(r.name)+' <span>'+esc(r.hanja)+'</span>';$('.hero-copy p').textContent=r.plant;$('.eyebrow').textContent='HERBAL MATERIA MEDICA';$('.pill').textContent='식약처 생약종합정보';$('.photo-label').remove();$('.overview').innerHTML='<div><p>기원<strong>'+esc(r.plant)+'</strong></p></div><div><p>자료 구분<strong>'+esc(r.category)+'</strong></p></div>';$('#basic table').innerHTML=[['생약명',r.name+' '+r.hanja],['기원',r.plant],['자료 구분',r.category],['학명 / 약용 부위','상세 원문 확인 후 제공'],['성미 / 귀경','전문 문헌 검토 후 제공'],['산지 / 이명','상세 원문 확인 후 제공']].map(([k,v])=>'<tr><th>'+esc(k)+'</th><td>'+esc(v)+'</td></tr>').join('');$('#basic .source-note').textContent='식약처 생약종합정보 · 목록 '+r.page+'쪽';for(const id of ['effects','usage']){const el=$('#'+id);const heading=el.querySelector('.section-heading').outerHTML;el.innerHTML=heading+'<div class="info-box"><h3>검토된 상세 정보가 없습니다</h3><p>식약처 목록에는 이름·기원·자료 구분이 제공됩니다. 이 항목은 상세 원문과 전문 문헌 확인 후 제공됩니다.</p></div>'}$('#safety .warning').innerHTML='<h3>복용 전 전문가와 상담하세요</h3><p>임신·수유 중이거나 약물을 복용 중인 경우 의료진에게 사용 여부를 확인하세요. 생약 전반의 일반 안내이며, 이 약재의 개별 금기·상호작용은 검토 전입니다.</p><a class="source-link" href="https://www.nccih.nih.gov/health/providers/digest/herb-drug-interactions" target="_blank" rel="noopener">NCCIH 안전성 안내 ↗</a>';$('#formulas .empty-block p').textContent='전문 문헌을 확인한 처방만 제공됩니다.';$('#sources .sources').innerHTML='<li><a href="'+esc(r.source)+'" target="_blank" rel="noopener">식품의약품안전평가원 · 생약종합정보 ↗</a><p>생약명·기원·자료 구분 · 목록 '+r.page+'쪽</p></li>'}document.title=r.name+' · 본초록 한약재 사전';$('.breadcrumb>span').innerHTML='한약재 사전 <i>/</i> <strong>'+esc(r.name)+'</strong>';bindArticle();render();$('.workspace').classList.remove('show-library');history.replaceState(null,'','?herb='+encodeURIComponent(id));window.scrollTo({top:0,behavior:'smooth'})}
$('#search').oninput=render;$('#all-filter').onclick=()=>{onlySaved=false;render()};$('#bookmark-filter').onclick=()=>{onlySaved=true;render()};$('#saved-nav').onclick=()=>{onlySaved=true;$('#search').value='';render();$('.workspace').classList.add('show-library');$('#search').focus()};$('#back-list').onclick=()=>{onlySaved=false;render();$('.workspace').classList.add('show-library');$('#search').focus()};$('.brand').onclick=e=>{e.preventDefault();openHerb('sophorae-flos')};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('.workspace').classList.add('show-library');$('#search').focus()}});bindArticle();fetch('herbs.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{records=data;$('.library-title>span').textContent=data.length;render();const id=new URLSearchParams(location.search).get('herb');openHerb(id&&records.some(r=>r.id===id)?id:'sophorae-flos')}).catch(()=>{$('#results').textContent='자료를 불러오지 못했습니다. 새로고침해 주세요.'});if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'set_herb_bookmark',description:'현재 약재의 기기 내 북마크를 추가하거나 해제합니다.',inputSchema:{type:'object',properties:{saved:{type:'boolean'}},required:['saved'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.saved!=='boolean')throw Error('saved must be boolean');return setBookmark(input.saved)}})).catch(()=>{})}catch{}
